  // 這是 #146 那張 5×5 網格（RATE_EXP × 樓層帶 pop 傾斜 k）上的 `0.70/1.5`，
  // 也是整張網格上唯一的 5/6。理由是 owner 回報「100 層、升滿級、6 個電梯，都可以 100%」
  // ——終期不該還是 100%。實測（3 顆種子 × 12 遊戲日）：100 樓少一井（7 井）
