  //     等」，那是「這個事件不存在」（零售帶量出來的懸崖，見上面 B）。
  //   patience 46 —— 懸崖右邊第一格，也是全表**成批出現的人裡最短的一個**。
  //          他們確實是最不願意等的，只是那個「最」被結構卡在 46 而不是 30。
  //   angry 1.8 —— **「沒有人願意等」改寫在這裡。** 他們放棄的時候扣 1.8 倍評價
