  //   patience 60 —— 比住戶（64）短一點，**因為上班會遲到**。這是這一批唯一一個
  //          有外部截止時間的事件（對照 #70 傍晚回家 68：回家沒有截止時間）。
  //          場上 60 × 2.267 = **136 秒**，懸崖右邊很遠——這是對的：12–20 個人
