export const tenantsFor = key => TENANTS.filter(t => t.bands.includes(key));
// 預設租戶（錨定租戶與舊存檔轉換用）＝這一帶標了 plain 的那個，不是表上的第一個
export const defaultTenant = key => {
  const list = tenantsFor(key);
  return ((list.find(t => t.plain) || list[0] || TENANTS[0]).id);
};
export const tenantById = id => TENANTS.find(t => t.id === id);

// ---------------------------------------------------------------- 突發流量事件（5.2 的 8）
// n     = 一次丟出幾個人；at 決定發生在哪一帶；to 決定他們要去哪
// hours = [a,b) 這個事件在一天中的哪一段可以發生。**a > b 代表跨午夜**：
//         [23,4] = 晚上 11 點到隔天凌晨 4 點。只有隨機池的事件需要 hours。
// block = [a,b] 封鎖這個事件發生的那一層 a–b 秒（選填）。**這是一個獨立的狀態機制**：
//         任何一列事件寫了它就會封鎖，沒寫的完全不受影響。封鎖期間電梯不以那層為
//         目標、不在那裡開門，**但那層照常產生乘客**（owner 裁決 #22：封鎖影響停靠，
//         不影響需求）——只有「以封鎖層為終點」的乘客不生。見 sim.js 的 blockFloor。
//         封鎖永遠不會落在大廳——40% 的行程有一端是大廳，封住它等於整棟樓停擺。
//         文案可以用 {s} 帶入封鎖秒數。
// blockOn = 'deliver'（選填）封鎖不在事件發生的瞬間開始，而是等這個事件生出來的乘客
//         被送到那一層才開始。沒寫就是原本的「立刻封」。配 inbound 用：打蠟的順序是
//         「清潔工搭電梯上去 → 到了才開始打蠟 → 那層封閉」。
//         這也讓封鎖變成**玩家的行為造成的**，而不是天上掉下來的罰款。
// blockText = blockOn:'deliver' 真的封起來的那一刻跳的提示（選填）。可用 {f} {s}。
// blockAfter = N（秒，選填，只對 blockOn:'deliver' 有意義）沒被送上去的話，這一批人
//         出現 N 秒之後自己走樓梯上去，封鎖照樣開始。沒寫就沒有上限——那等於
//         「不理他們 = 永遠不封鎖 = 零成本」，一個支配策略。見 sim.js 的 stairsUp。
// blockLateText = blockAfter 觸發（他們自己走樓梯上去）時跳的提示（選填）。可用 {f} {s}。
//         沒寫就退回 blockText，不會變成一則空白的提示。
// inbound = true（選填）事件的樓層是**終點**，人往那裡去；此時 `to` 說的是他們**從哪來**。
//         沒寫的事件方向跟以前一樣（從事件樓層出發、去 to 那一帶）。
//         inbound 的事件不設疏散目標：人潮在起點，指到事件樓層只會讓玩家白按一次冷卻。
// stall = [a,b]（選填，#111 電力突波）**所有**電梯井強制停機 a–b 秒。走的是既有的
//         `s.lock` 狀態機（超速過熱用的那一個），不是第二套「電梯不能動」——
//         所以停機期間的行為跟過熱逐字相同：不移動、不開門、熱量歸零之後恢復。
//         沒寫的事件一個位元組都沒變。文案可以用 {s} 帶入停機秒數。
//         ⚠ 它跟 `block` 不一樣：block 是**一層樓**不能停靠，stall 是**所有車**都不動。
// ratingLift = [amount, secs]（選填，#114 諾貝爾獎來訪）事件發生的瞬間 `st.rating`
//         + amount，secs 秒之後扣回同樣的 amount。
//         ⚠ **評價有夾限（RATING_MIN/MAX）而且會往 RATING_DRIFT_TO 漂移**，所以
//         「扣回」不保證回到原本那個值（4.9 + 0.35 被夾在 5.0，扣回是 4.65）。
//         **這是寫下來的失真，不是 bug**：要精準就得把加值前的評價存起來，
//         而那會把一個暫時的加值變成一個要進存檔的狀態（設計 4.13：存檔只存 GameState）。
// type  = 這個事件生出來的人一律是這個人物 id（選填）
// types = { 人物id: 權重, … } 按權重混（選填，優先於 type）
//         兩個都沒寫 → 照出發樓層那一帶抽，跟這兩個欄位不存在時完全一樣。
//         這是「大廳出發的飯店事件要生出房客」唯一能表達的方式：大廳屬零售帶，
//         照樓層抽永遠抽不到 band:'hotel' 的房客。
