  //       重抽一次 other，所以 at:'office' to:'office' 不加 inbound 的話，起點固定、
  //       終點各自亂抽——那是「一層樓的人散到各層」，剛好相反。inbound 把事件樓層
  //       變成**終點**（大會的那一層，固定），ev.to 說的是他們**從哪來**（每個人各自
  //       重抽一個辦公層）。
  //   ⚠ 兩個我沒有偷偷解掉的副作用：
  //       1. runEvent 對 `to === o` 是 continue，而這一列兩端都是辦公帶，所以
  //          **抽到大會那一層的人會蒸發**——辦公帶蓋滿 10 層時約 1/10。提示裡的
  //          {n} 印的是真的生出來的數字，不是資料上寫的 n。
  //       2. inbound 的事件不設 sim.surgeFloor，所以**疏散模式對這一列沒有用**。
