  //   w:26 —— 10–16 點是全天最擠的窗（既有 112–150）。26 大約 12–15%，實測
  //       **0.52 次／10 遊戲日 ≈ 每 19 個遊戲日一次 = 一「場」一次**。
  //       ⚠ **這個數字我壓過一次：第一版 44，實測 0.78 次／10 日。** 打臉的不是頻率
