  // 加班到深夜（#46）。owner 指定：辦公 → 大廳、3–6 人、21–24 點、單價高。
  //   hours:[21,2] —— **跨午夜，用的是 #9 修好的 inHourWindow()**（a > b 代表跨午夜；
  //       舊寫法 `h < a || h >= b` 在跨午夜時兩端都打不到）。
  //       ⚠ **owner 寫的是 21–24，我往後延了兩小時，這一條要請 orchestrator 過目。**
  //       理由有兩層：(1) 「加班到**深夜**」這五個字在 24 點就結束是講不通的；
