  //       這正好是這一列該有的形狀：一個**每隔幾天的深夜小事件**，讓 22:00 之後
  //       不再是一片空白。
  //   n:[3,6] —— owner 指定。它是這九個裡最小的一批，配上 patience 72，
  //       實測存活率 20–58%／endgame 94%，是這一批的上緣——**這是對的**：
