  //   hours:[8,19] —— owner 寫「任意」，收窄的理由與量測見上面的 D，窗跟 #45 共用
  //       同一個（辦公帶自己的作息），**一個窗寫一次理由**。
  //   w:5 —— 跟系統當機並列全表最低。裁員日是「那一天」的事件（對照零售帶的
  //       週年慶 20 / 新品首賣 20——它們的窗只有 2 小時，這一列的窗有 11 小時，
