  // ================================================================ 住宅帶的十個事件（#69–#78）
  //
  // 十列共用的紀律，先寫在這裡，下面就不逐列重複：
  //
  // **A. `hours` 的窗沒有一個窄於 2 小時，而且這是結構性的、不是品味。**
  //    事件檢查每 `EVENT_EVERY` 75 秒一次，而一天是 `DAY_SECONDS` 180 秒，
  //    所以每一次檢查固定前進 **75 ÷ 180 × 24 = 10.002 個遊戲小時**。
  //    `gcd(10, 24) = 2` → **任何一個時刻，時鐘上只有十二個偶數整點抽得到**。
  //    半開區間 `[a, a+2)` 保證裡面剛好有一個偶數整點；`[a, a+1)` 在 a 是奇數時
  //    **一次都不會命中**——實測一個 `[7,8)` 的窗前 150 個遊戲日 0 次，
  //    然後（那 0.002 的漂移累積起來）活兩百天，然後再消失。
  //    **在測試裡是零，在某個玩家的存檔裡是正常頻率。**
  //    我這十列最窄的是 [7,9)／[6,8)／[8,10)／[18,20)／[19,21)，都剛好 2 小時。
  //
  // **B. 「任意時段」寫成 `hours:[0,24)`，不是省略 `hours`。**
  //    `fireEvent` 的過濾是 `inHourWindow(h, e.hours)`，而 `inHourWindow(h, null)`
  //    回 true，所以省略也會動。但省略讀起來像「忘了填」，`[0,24]` 讀起來是
  //    「我想過了，答案是全天」。#71 #73 #78 三列是 owner 指定的「任意」。
  //
  // **C. `w` 是「在窗裡贏誰」，不是「多常發生」。**
  //    隨機事件的檢查是全域的：75 秒一次 × 0.55 = **一個遊戲日 1.32 次事件**。
  //    一個占一天 8.3% 的兩小時窗，就算是那個窗裡唯一的事件，上限也只有
  //    0.11 次/日 ≈ 九個遊戲日一次。**窄的 hours 決定頻率，w 只決定在窗裡贏誰。**
  //    （#20 打烊清場與 #22 打蠟第二次配平都得到同一條結論。）
  //
  // **D. 這十列是把同一塊餅重新分，不是「事件變多」。**
  //    辦公帶加九列之後既有事件的頻率掉了約 30%。我這一支量到的既有事件頻率
  //    **不是最終值**——住宅帶的五個人物（#79–#83）那一支合併進來之後還會再動一次。
  //    實測的前後對照寫在交付留言。
  //
  // **E. 五列指到另一個 peer 的人物型別（#79–#83），這裡沒有那五列的定義。**
  //    `type:` 打錯字是**安靜退回樓層帶抽樣**（症狀是「停電疏散了一隻貓」），
  //    harness 第 11 組會抓。逐列標了它指的是哪一張 issue。
  //
  // **F. 實測（70 層、4 井、cap 6、LOOK+FIFO、釘住種子、400 個遊戲日）。**
  //    ⚠ **70 層不是隨便挑的**：住宅帶是 46–70 樓，而 #87 那次量測是 **45 層**——
  //    那座塔裡住宅帶根本不存在，所以 #87 的表裡一列住宅事件都不可能出現，
  //    **我這十列沒辦法跟那張表逐列對照**。
  //
  //      每 10 個遊戲日：              w    hours      實測    該窗上限   佔上限
  //      movingday   搬家車隊          6   [0,24)     1.06     13.2       8%
  //      watercut    停水通知          5   [0,24)     0.88     13.2       7%
  //      latenight   半夜回家         24   [0,3)      0.84      2.1      39%
  //      blackout    停電              3   [0,24)     0.53     13.2       4%
  //      dogwalk     遛狗時間         24   [6,8)      0.48      1.1      43%
  //      eveninghome 傍晚回家         26   [18,21)    0.37      2.1      17%
  //      fooddelivery外送高峰         26   [18,20)    0.20      1.1      18%
  //      morningrush 早晨通勤         30   [7,9)      0.18      1.1      16%
  //      blockparty  社區聚會         22   [19,21)    0.15      1.1      14%
  //      renovation  裝修工班         20   [8,10)     0.11      1.1      10%
