  //    **`w` 最高的那一列（morningrush 30）是倒數第三少的，`w` 最低的那一列
  //    （blackout 3）比其中六列都常見。** 兩把獨立的尺（解析：沿梳齒累加
  //    EVENT_CHANCE×w/Σw；端對端：跑 sim 用 `sim.lastEvent` 認事件）在每一列上
  //    差 < 0.1，所以這不是量測誤差。
  //
  // **G. 對 #87 的一條修正：那個 1/12 不是梳齒造成的，denser 齒救不了它。**
  //    #87 把它寫成「一個兩小時的窗只蓋到十二個齒裡的一個」，並列了
  //    「(丙) 縮短 EVENT_EVERY 讓齒變密」當候選。我量了全部 40 列 400 個遊戲日的
  //    實際覆蓋率，**`覆蓋率 ÷ (窗寬/24)` 落在 0.97–1.02 之間**——
  //    因為那 0.002 的漂移會讓整把梳子進動，跑得夠久之後覆蓋率就收斂到
  //    **窗寬占一天的比例**，跟齒有多密無關。
  //    也就是說：**兩小時的窗拿到 1/12，不是因為梳子，是因為它一天只開兩小時。**
  //    梳齒真正製造的病理只有兩個：(1) 窄於齒距的窗會**長期為零**
