  //
  // ⚠ **`type:'latehome'` 是 #82 那一支的型別 id**（我原本的暫定值是 `nightreturner`；
  //   orchestrator 掃過之後給的真 id 是 `latehome`，fare 2.4 / patience 90 / size 1 / w:70）。
  //   在 #82 落地之前這個字串指不到，harness 第 11 組會紅。
  //
  //   w:24 —— [0,3) 三小時窗。**這是我這十列裡最值得的一個權重**，因為
