  //
  //              5 層   12 層   40 層  100 層   全體平均   → 門檻   約幾場（12 層）
  //   waxClean   0.88–1.13  1.00–1.13  1.00–1.75  0.88–2.38   1.20      4       3.6
  //   crewIntact 6.4–11.5   3.5–10.5   6.4–13.1   10.0–28.3  10.44     25       3.4
