  //   protoDemo        1.50    1.88    1.69       5        （事件生的技師送到幾個）
  //   animalRound      2.13    0.88    1.51       4        （事件生的管理員送到幾個）
  //   surgeRide        0.13    0.25    0.19       5        ⚠ 見下，這一條不能用 100 層量
  //
  // ⚠ **`leaker` 的送達率 17–24% 是全帶最低，而那不是缺陷**：E2 的 panic 0.25 是
