  //   8–14 秒的停機期間期望值就有一兩個）。而 `powersurge` 的 `at:'any'`，
  //   **它在 5 層就在池子裡**。實測每場拿到幾次：
  //       12 層 / FIFO / 1 井 / cap 4   **3.25**（8 場觸發 45 次，成功 26 次 = 58%）
  //       40 層 / LOOK / 3 井 / cap 6   **0.88**（觸發 10 次，成功 7 次 = 70%）
  //      100 層 / LOOK / 4 井 / cap 8   **0.13**
  //   取 5 ≈ **12 層的一場半**。這是一條**早期就拿得到**的成就，而 codex 跨拆樓保留，
